            break
        }
    }
    if !found || beginWord == endWord {
        return 0
    }

    n := len(wordList)
    m := len(wordList[0])
    adj := make([][]int, n)
    mp := make(map[string]int)
    for i := 0; i < n; i++ {
        mp[wordList[i]] = i
        adj[i] = []int{}
    }

    for i := 0; i < n; i++ {
        for j := i + 1; j < n; j++ {
            cnt := 0
            for k := 0; k < m; k++ {
                if wordList[i][k] != wordList[j][k] {
                    cnt++
                }
            }
            if cnt == 1 {
                adj[i] = append(adj[i], j)
                adj[j] = append(adj[j], i)
            }
        }
    }

