            if byte(c) == beginWord[i] {
                continue
            }
            word := beginWord[:i] + string(c) + beginWord[i+1:]
            if idx, ok := mp[word]; ok && !visit[idx] {
                q = append(q, idx)
                visit[idx] = true
            }
        }
    }

    for len(q) > 0 {
        res++
